const express = require('express');

router.post("/vuln", (req, res) => {
  const password = req.body.password;
  const user = {
     user: "user",
     password: password,
  };
  function getUser() {
     return new Promise((resolve, reject) => {
         resolve(user);
     });
  }
  function getUserPassword(user) {
     return new Promise((resolve, reject) => {
         if (user.password === undefined) {
            reject(new Error("login fail"));
         } else {
            resolve(user);
         }
     });
  }

  function checkPassword(user) {
    return new Promise((resolve, reject) => {
        if (user.password == "abc") {
           resolve(user);
        } else {
           reject(new Error("login fail"));
        }
    });
  }
  return getUser()
    .then(getUserPassword)
    .then(checkPassword)
    .then((result) => res.send(result))
    .catch((err) => {
        // 서로 다른 예외 상황에서도 동일한 에러 메시지만 출력
        res.send(err.message);
    });
});

code_examples.safe:
const express = require('express');

router.post("/patched", (req, res) => {
  const password = req.body.password;
  const user = {
     user: "user",
     password: password,
  };
  function getUser() {
     return new Promise((resolve, reject) => {
         resolve(user);
     });
  }
  function getUserPassword(user) {
     return new Promise((resolve, reject) => {
         if (user.password === undefined) {
            reject(new Error("password required"));
         }
         resolve(user);
     });
  }
  function checkPassword(user) {
     return new Promise((resolve, reject) => {
         if (user.password == "abc") {
             resolve(user);
         } else {
             reject(new Error("wrong password"));
         }
     });
  }
  return getUser()
     .then(getUserPassword)
     .then(checkPassword)
     .then((result) => res.send(result))
     .catch((err) => {
         // 예외 상황에 맞는 처리 결과 메시지를 로그에 기록(내장 함수 log가 있다고 가정)
         log(err.messsage);
         // 클라이언트에는 에러 발생 여부만 전달
         res.send('login failed');
     });
});
